#[derive(Serialize, Deserialize)]
#[serde(tag = "type")]
enum Command {
    ReserveStock { order_id: String, qty: u32 },
    CancelOrder { order_id: String },
}

async fn run(mut rx: mpsc::Receiver<Command>) {
    while let Some(cmd) = rx.recv().await {
        match cmd { Command::ReserveStock { order_id, qty } => reserve(&order_id, qty),
                    Command::CancelOrder { order_id } => cancel(&order_id) }
    }
}
